import sys
from collections import deque

MOD = 998244353

def main():
    input = sys.stdin.readline
    N, M = map(int, input().split())
    A = [x - 1 for x in map(int, input().split())]

    rev = [[] for _ in range(N)]
    indeg = [0] * N
    for i, a in enumerate(A):
        rev[a].append(i)
        indeg[a] += 1

    q = deque(i for i in range(N) if indeg[i] == 0)
    removed = [False] * N
    order = []

    while q:
        u = q.popleft()
        removed[u] = True
        order.append(u)
        v = A[u]
        indeg[v] -= 1
        if indeg[v] == 0:
            q.append(v)

    is_cycle = [not removed[i] for i in range(N)]

    # pref[u][v] = number of valid assignments in subtree rooted at u
    # when parent of u has value at most v, i.e. sum_{x_u=1..v} exact[u][x_u].
    pref = [None] * N

    for u in order:
        exact = [0] + [1] * M
        for ch in rev[u]:
            if is_cycle[ch]:
                continue
            cp = pref[ch]
            for v in range(1, M + 1):
                exact[v] = exact[v] * cp[v] % MOD

        acc = 0
        for v in range(1, M + 1):
            acc += exact[v]
            if acc >= MOD:
                acc -= MOD
            exact[v] = acc
        pref[u] = exact

    seen = [False] * N
    ans = 1

    for s in range(N):
        if not is_cycle[s] or seen[s]:
            continue

        cycle = []
        u = s
        while not seen[u]:
            seen[u] = True
            cycle.append(u)
            u = A[u]

        ways_by_value = [1] * (M + 1)

        for node in cycle:
            for ch in rev[node]:
                if is_cycle[ch]:
                    continue
                cp = pref[ch]
                for v in range(1, M + 1):
                    ways_by_value[v] = ways_by_value[v] * cp[v] % MOD

        comp = sum(ways_by_value[1:]) % MOD
        ans = ans * comp % MOD

    print(ans)

if __name__ == "__main__":
    main()
